update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(67,null::text,$$Fiscalização do Ministério Público$$,$$O Ministério Público fiscaliza a execução da pena e da medida de segurança, oficiando no processo executivo e nos incidentes da execução.$$),
(68,null,$$Incumbências do Ministério Público$$,$$Incumbe ao Ministério Público fiscalizar a regularidade formal das guias de recolhimento e de internamento (inciso I), requerer providências, incidentes de excesso ou desvio, medida de segurança, conversão de penas, progressão ou regressão e internação (inciso II, a a f) e interpor recursos das decisões proferidas durante a execução (inciso III). O órgão visita mensalmente os estabelecimentos penais, registrando a presença em livro próprio (parágrafo único).$$),
(69,null,$$Conselho Penitenciário$$,$$O Conselho Penitenciário é órgão consultivo e fiscalizador da execução da pena. É integrado por membros nomeados pelo Governador do Estado, do Distrito Federal e dos Territórios, dentre professores e profissionais da área do Direito Penal, Processual Penal, Penitenciário e ciências correlatas e representantes da comunidade (§ 1º), com mandato de 4 (quatro) anos (§ 2º).$$),
(70,null,$$Atribuições do Conselho Penitenciário$$,$$Incumbe ao Conselho emitir parecer sobre indulto e comutação de pena, excetuada a hipótese de pedido de indulto com base no estado de saúde do preso (inciso I), inspecionar os estabelecimentos e serviços penais (inciso II), apresentar relatório anual ao Conselho Nacional de Política Criminal e Penitenciária, no primeiro trimestre (inciso III), e supervisionar os patronatos e a assistência aos egressos (inciso IV).$$),
(71,null,$$Departamento Penitenciário Nacional$$,$$O Departamento Penitenciário Nacional, subordinado ao Ministério da Justiça, é órgão executivo da Política Penitenciária Nacional e de apoio administrativo e financeiro do Conselho Nacional de Política Criminal e Penitenciária.$$),
(72,null,$$Atribuições do Departamento Penitenciário Nacional$$,$$São atribuições do Departamento acompanhar a aplicação das normas de execução penal em todo o território nacional (inciso I), inspecionar e fiscalizar periodicamente os estabelecimentos e serviços penais (inciso II), assistir tecnicamente as unidades federativas (inciso III) e estabelecer, mediante convênios, o cadastro nacional de vagas (inciso VI). Incumbem-lhe também a coordenação e a supervisão dos estabelecimentos penais e de internamento federais (§ 1º).$$),
(73,null,$$Departamento Penitenciário local$$,$$A legislação local pode criar Departamento Penitenciário ou órgão similar, com as atribuições que estabelecer.$$),
(74,null,$$Finalidade do Departamento local$$,$$O Departamento Penitenciário local, ou órgão similar, tem por finalidade supervisionar e coordenar os estabelecimentos penais da Unidade da Federação a que pertencer. O parágrafo único atribui a esses órgãos o acompanhamento de que trata o inciso VII do caput do art. 72.$$),
(75,null,$$Requisitos do diretor de estabelecimento$$,$$O diretor de estabelecimento deve ser portador de diploma de nível superior de Direito, Psicologia, Ciências Sociais, Pedagogia ou Serviços Sociais (inciso I), possuir experiência administrativa na área (inciso II) e ter idoneidade moral e reconhecida aptidão (inciso III). Deve residir no estabelecimento ou nas proximidades e dedicar tempo integral à função (parágrafo único).$$),
(76,null,$$Quadro do Pessoal Penitenciário$$,$$O Quadro do Pessoal Penitenciário é organizado em diferentes categorias funcionais, segundo as necessidades do serviço, com especificação de atribuições relativas às funções de direção, chefia e assessoramento do estabelecimento e às demais funções.$$),
(77,null,$$Escolha do pessoal penitenciário$$,$$A escolha do pessoal administrativo, especializado, de instrução técnica e de vigilância atende à vocação, à preparação profissional e aos antecedentes pessoais do candidato. O ingresso, a progressão e a ascensão funcional dependem de cursos específicos de formação, com reciclagem periódica dos servidores (§ 1º), e, no estabelecimento para mulheres, só se permite o trabalho de pessoal do sexo feminino, salvo pessoal técnico especializado (§ 2º).$$),
(78,null,$$Patronato$$,$$O Patronato, público ou particular, destina-se a prestar assistência aos albergados e aos egressos (artigo 26).$$),
(79,null,$$Incumbências do Patronato$$,$$Incumbe também ao Patronato orientar os condenados à pena restritiva de direitos (inciso I), fiscalizar o cumprimento das penas de prestação de serviço à comunidade e de limitação de fim de semana (inciso II) e colaborar na fiscalização das condições da suspensão e do livramento condicional (inciso III).$$),
(80,null,$$Conselho da Comunidade$$,$$Haverá em cada comarca um Conselho da Comunidade, composto no mínimo por um representante de associação comercial ou industrial, um advogado indicado pela Seção da Ordem dos Advogados do Brasil, um Defensor Público indicado pelo Defensor Público Geral e um assistente social escolhido pela Delegacia Seccional do Conselho Nacional de Assistentes Sociais. Na falta da representação, o juiz da execução escolhe os integrantes (parágrafo único).$$),
(81,null,$$Incumbências do Conselho da Comunidade$$,$$Incumbe ao Conselho visitar, pelo menos mensalmente, os estabelecimentos penais da comarca (inciso I), entrevistar presos (inciso II), apresentar relatórios mensais ao juiz da execução e ao Conselho Penitenciário (inciso III) e diligenciar a obtenção de recursos materiais e humanos para melhor assistência ao preso ou internado (inciso IV).$$),
(81,$$Art. 81-A$$,$$Defensoria Pública na execução penal$$,$$A Defensoria Pública vela pela regular execução da pena e da medida de segurança, oficiando no processo executivo e nos incidentes da execução, para a defesa dos necessitados em todos os graus e instâncias, de forma individual e coletiva.$$),
(81,$$Art. 81-B$$,$$Incumbências da Defensoria Pública$$,$$Incumbe ainda à Defensoria Pública requerer as providências e os incidentes listados no inciso I (a a l), requerer a emissão anual do atestado de pena a cumprir (inciso II), interpor recursos de decisões judiciais ou administrativas durante a execução (inciso III), representar para instauração de sindicância ou procedimento administrativo (inciso IV), visitar os estabelecimentos penais (inciso V) e requerer a interdição, total ou parcial, de estabelecimento penal (inciso VI). O órgão visita periodicamente os estabelecimentos, registrando a presença em livro próprio (parágrafo único).$$),
(82,null,$$Destinatários dos estabelecimentos penais$$,$$Os estabelecimentos penais destinam-se ao condenado, ao submetido à medida de segurança, ao preso provisório e ao egresso. A mulher e o maior de sessenta anos são recolhidos, separadamente, a estabelecimento próprio e adequado à sua condição pessoal (§ 1º), e o mesmo conjunto arquitetônico pode abrigar estabelecimentos de destinação diversa, desde que devidamente isolados (§ 2º).$$),
(83,null,$$Áreas e serviços do estabelecimento penal$$,$$O estabelecimento penal deve contar, conforme sua natureza, com áreas e serviços destinados a assistência, educação, trabalho, recreação e prática esportiva. Os parágrafos preveem instalação para estágio de estudantes universitários (§ 1º), berçário nos estabelecimentos para mulheres (§ 2º), salas de aula para ensino básico e profissionalizante (§ 4º) e instalação destinada à Defensoria Pública (§ 5º).$$),
(83,$$Art. 83-A$$,$$Execução indireta de atividades materiais$$,$$Podem ser objeto de execução indireta as atividades materiais acessórias, instrumentais ou complementares desenvolvidas em estabelecimentos penais, notadamente serviços de conservação, limpeza, informática, copeiragem, portaria, recepção, reprografia, telecomunicações, lavanderia e manutenção de prédios (inciso I) e serviços relacionados à execução de trabalho pelo preso (inciso II). A execução indireta ocorre sob supervisão e fiscalização do poder público (§ 1º).$$),
(83,$$Art. 83-B$$,$$Funções indelegáveis$$,$$São indelegáveis as funções de direção, chefia e coordenação no âmbito do sistema penal e as atividades que exijam o exercício do poder de polícia, notadamente a classificação de condenados (inciso I), a aplicação de sanções disciplinares (inciso II), o controle de rebeliões (inciso III) e o transporte de presos para órgãos do Poder Judiciário, hospitais e outros locais externos (inciso IV).$$),
(84,null,$$Separação de presos$$,$$O preso provisório fica separado do condenado por sentença transitada em julgado. Os presos provisórios são separados conforme acusados de crimes hediondos ou equiparados, de crimes com violência ou grave ameaça à pessoa, ou de outros crimes ou contravenções (§ 1º, incisos I a III), e os condenados, conforme os critérios do § 3º (incisos I a IV). O preso que, ao tempo do fato, era funcionário da Administração da Justiça Criminal fica em dependência separada (§ 2º), e o que tiver a integridade ameaçada pela convivência com os demais fica segregado em local próprio (§ 4º).$$),
(85,null,$$Lotação do estabelecimento penal$$,$$O estabelecimento penal deve ter lotação compatível com sua estrutura e finalidade. O Conselho Nacional de Política Criminal e Penitenciária determina o limite máximo de capacidade do estabelecimento, atendendo a sua natureza e peculiaridades (parágrafo único).$$),
(86,null,$$Execução da pena em outra unidade federativa$$,$$As penas privativas de liberdade aplicadas pela Justiça de uma Unidade Federativa podem ser executadas em outra unidade, em estabelecimento local ou da União. A União pode construir estabelecimento penal em local distante da condenação, quando a medida se justifique no interesse da segurança pública ou do próprio condenado (§ 1º). O juiz competente define, no prazo de 24 (vinte e quatro) horas, o estabelecimento adequado, a requerimento da administração penitenciária (§ 3º), e o § 5º trata da transferência excepcional em caso de risco iminente e grave, com comunicação imediata ao juiz competente, que decide em 24 (vinte e quatro) horas.$$),
(87,null,$$Penitenciária$$,$$A penitenciária destina-se ao condenado à pena de reclusão, em regime fechado. O parágrafo único permite à União, aos Estados, ao Distrito Federal e aos Territórios construir penitenciárias destinadas exclusivamente aos presos provisórios e condenados em regime fechado sujeitos ao regime disciplinar diferenciado, nos termos do art. 52.$$),
(88,null,$$Cela individual$$,$$O condenado é alojado em cela individual, que conterá dormitório, aparelho sanitário e lavatório. São requisitos básicos da unidade celular a salubridade do ambiente (aeração, insolação e condicionamento térmico adequado) e a área mínima de 6,00m2 (seis metros quadrados) (parágrafo único, alíneas a e b).$$),
(89,null,$$Penitenciária de mulheres$$,$$Além dos requisitos do art. 88, a penitenciária de mulheres é dotada de seção para gestante e parturiente e de creche para abrigar crianças maiores de 6 (seis) meses e menores de 7 (sete) anos, com a finalidade de assistir a criança desamparada cuja responsável estiver presa. A seção e a creche exigem atendimento por pessoal qualificado e horário de funcionamento que garanta a melhor assistência à criança e à sua responsável (parágrafo único, incisos I e II).$$),
(90,null,$$Penitenciária de homens$$,$$A penitenciária de homens é construída em local afastado do centro urbano, a distância que não restrinja a visitação.$$)
) as v(n,t,c,a) where l.codigo='lep' and l.numero=v.n and l.titulo is not distinct from v.t and l.inciso is null and l.paragrafo is null and l.texto like 'Art%' and l.vigente;